const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Define the geometry for Acre, Brazil
    // Polygon generated from searching "Acre, Brazil" in Google Earth Engine Code Editor
    const acre = ee.Geometry.Polygon(
      [[[-74.00, -7.00], [-74.00, -12.00], [-66.00, -12.00], [-66.00, -7.00]]], null, false
    );

    // Define the specific monthly images for comparison
    const jul_2005_start = '2005-07-01';
    const jul_2005_end = '2005-07-31'; // MCD64A1 is monthly, so we want the image *for* July.
    const sep_2005_start = '2005-09-01';
    const sep_2005_end = '2005-09-30'; // And the image *for* September.

    // 2. Data Acquisition & Check
    const burnedAreaCollection = ee.ImageCollection('MODIS/051/MCD64A1');

    // Filter for July 2005
    const jul2005Image = burnedAreaCollection
      .filterDate(jul_2005_start, jul_2005_end)
      .first();

    // Filter for September 2005
    const sep2005Image = burnedAreaCollection
      .filterDate(sep_2005_start, sep_2005_end)
      .first();

    if (!jul2005Image) {
      console.log("No MODIS MCD64A1 image found for July 2005.");
      console.log("C1");
      return;
    }
    if (!sep2005Image) {
      console.log("No MODIS MCD64A1 image found for September 2005.");
      console.log("C1");
      return;
    }

    // MCD64A1 'BurnDate' band values are ordinal day of the year.
    // Day of year for July (1-31): 182-212
    // Day of year for September (1-30): 244-273

    // Function to calculate burned area for a given month's image
    const calculateBurnedArea = (image, startDayOfYear, endDayOfYear, geom, periodName) => {
      // Mask pixels outside the target month's burn dates
      // And mask out unburned areas (BurnDate == 0)
      const burnedPixels = image.select('BurnDate')
        .updateMask(image.select('BurnDate').gt(0)) // Ensure it's a burn
        .updateMask(image.select('BurnDate').gte(startDayOfYear)) // Burned within the period
        .updateMask(image.select('BurnDate').lte(endDayOfYear)); // Burned within the period

      // Get pixel count of valid (burned) pixels
      const pixelCount = burnedPixels.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: 500, // MCD64A1 nominal resolution is 500m
        maxPixels: 1e9,
        tileScale: 16
      }).get('BurnDate').getInfo();

      if (pixelCount === 0) {
        console.log(`No valid burned pixels found for ${periodName}.`);
        return 0; // Return 0 if no valid pixels
      } else if (pixelCount === null) {
        console.log(`Calculation failure for pixel count in ${periodName}.`);
        throw new Error("C3");
      }

      // Calculate area per pixel in square meters (500m x 500m)
      const pixelAreaSqMeters = 500 * 500;
      const totalBurnedAreaSqMeters = pixelCount * pixelAreaSqMeters;

      // Convert to hectares (1 ha = 10,000 sq meters)
      const totalBurnedAreaHectares = totalBurnedAreaSqMeters / 10000;

      return totalBurnedAreaHectares;
    };

    // Calculate burned area for July 2005
    const julBurnedArea = calculateBurnedArea(jul2005Image, 182, 212, acre, "July 2005");
    // If calculateBurnedArea returns 0, it means no valid pixels, so C2 for that period
    if (julBurnedArea === 0) {
      console.log("C2");
      return;
    } else if (typeof julBurnedArea !== 'number' || isNaN(julBurnedArea)) {
      // This case is covered by the throw new Error in calculateBurnedArea, but good to have a check
      console.log("C3");
      return;
    }

    // Calculate burned area for September 2005
    const sepBurnedArea = calculateBurnedArea(sep2005Image, 244, 273, acre, "September 2005");
    if (sepBurnedArea === 0) {
      console.log("C2");
      return;
    } else if (typeof sepBurnedArea !== 'number' || isNaN(sepBurnedArea)) {
      console.log("C3");
      return;
    }

    console.log(`Burned area in Acre, July 2005: ${julBurnedArea.toFixed(2)} hectares`);
    console.log(`Burned area in Acre, September 2005: ${sepBurnedArea.toFixed(2)} hectares`);

    // 5. Validation & Final Answer
    if (sepBurnedArea > julBurnedArea) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    if (error.message === "C3") {
      console.log("C3");
    } else {
      console.error("An unexpected error occurred: ", error);
      console.log("D"); // General error/syntax/method issue
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

